using Microsoft.Extensions.DependencyInjection;
using Shouldly;
using VinayakaAgencies.Application.Einvoicing;
using VinayakaAgencies.Domain.Einvoicing;
using VinayakaAgencies.Infrastructure.Tests.TestSupport;

namespace VinayakaAgencies.Infrastructure.Tests.Einvoicing;

/// <summary>
/// The e-way bill workflow end to end against a recorded portal
/// (phase-6-einvoice-eway.md §2, checkpoint C6.2).
/// </summary>
/// <remarks>
/// C6.2 asks that a bill be generated by IRN in the sandbox. The sandbox half needs the credentials
/// <c>open-questions.md</c> #10 is still waiting on; what is verified here is everything up to the
/// wire — that the bill is generated <em>by IRN</em> rather than from invoice detail, that the portal's
/// expiry is what gets stored, and that Part-B, cancellation and extension behave.
/// </remarks>
public sealed class EwayBillWorkflowTests
{
    private static readonly EwayBillPartB ByRoad = new(
        TransportMode.Road,
        VehicleType.Regular,
        VehicleNumber: "KA01AB1234",
        TransporterName: "Sri Lakshmi Transports");

    [Fact]
    public async Task GenerateAsync_ForARegisteredInvoice_IsGeneratedByIrn()
    {
        var portal = new RecordedIrpServer();
        await using var host = EinvoiceTestWorld.NewHost(portal);
        var world = await EinvoiceTestWorld.ArrangeAsync(host);

        var registration = await host.InScopeAsync(sp =>
            sp.GetRequiredService<IEinvoiceService>().GenerateAsync(world.InvoiceId));

        var bill = await host.InScopeAsync(sp =>
            sp.GetRequiredService<IEwayBillService>()
                .GenerateAsync(world.InvoiceId, distanceKilometres: 450, ByRoad));

        bill.Status.ShouldBe(EwayBillStatus.Active);
        bill.EwayBillNumber.ShouldNotBeNull();

        // By IRN, which is the whole point of the route the spec asks for.
        bill.Irn.ShouldBe(registration.Registration.Irn);
        portal.Calls.ShouldContain(nameof(RecordedIrpServer.GenerateEwayBillByIrnAsync));
    }

    [Fact]
    public async Task GenerateAsync_ForAnUnregisteredInvoice_IsRefusedBeforeCallingThePortal()
    {
        var portal = new RecordedIrpServer();
        await using var host = EinvoiceTestWorld.NewHost(portal);
        var world = await EinvoiceTestWorld.ArrangeAsync(host);

        await Should.ThrowAsync<InvalidOperationException>(() => host.InScopeAsync(sp =>
            sp.GetRequiredService<IEwayBillService>()
                .GenerateAsync(world.InvoiceId, 450, ByRoad)));

        portal.Calls.ShouldNotContain(nameof(RecordedIrpServer.GenerateEwayBillByIrnAsync));
    }

    [Fact]
    public async Task GenerateAsync_StoresThePortalsExpiry_NotOurOwnCalculation()
    {
        var portal = new RecordedIrpServer();
        await using var host = EinvoiceTestWorld.NewHost(portal);
        var world = await EinvoiceTestWorld.ArrangeAsync(host);

        await host.InScopeAsync(sp =>
            sp.GetRequiredService<IEinvoiceService>().GenerateAsync(world.InvoiceId));

        var bill = await host.InScopeAsync(sp =>
            sp.GetRequiredService<IEwayBillService>().GenerateAsync(world.InvoiceId, 450, ByRoad));

        // The recorded portal issues at 2026-09-17 17:45 IST and grants three days for 450 km regular,
        // i.e. 2026-09-20 17:45 IST = 12:15 UTC.
        bill.ValidUntilUtc.ShouldBe(new DateTimeOffset(2026, 9, 20, 12, 15, 0, TimeSpan.Zero));
    }

    [Fact]
    public async Task GenerateAsync_ForAnActiveBill_RefusesRatherThanIssuingASecond()
    {
        var portal = new RecordedIrpServer();
        await using var host = EinvoiceTestWorld.NewHost(portal);
        var world = await EinvoiceTestWorld.ArrangeAsync(host);

        await host.InScopeAsync(sp =>
            sp.GetRequiredService<IEinvoiceService>().GenerateAsync(world.InvoiceId));
        await host.InScopeAsync(sp =>
            sp.GetRequiredService<IEwayBillService>().GenerateAsync(world.InvoiceId, 450, ByRoad));

        await Should.ThrowAsync<InvalidOperationException>(() => host.InScopeAsync(sp =>
            sp.GetRequiredService<IEwayBillService>().GenerateAsync(world.InvoiceId, 450, ByRoad)));
    }

    [Fact]
    public async Task IsRequiredForDocumentAsync_ComparesTheConsignmentValueToTheConfiguredThreshold()
    {
        var portal = new RecordedIrpServer();
        await using var host = EinvoiceTestWorld.NewHost(portal);
        var world = await EinvoiceTestWorld.ArrangeAsync(host);

        // The arranged invoice is ₹1,000 taxable + ₹180 IGST = ₹1,180, well under the ₹50,000 default.
        (await host.InScopeAsync(sp =>
                sp.GetRequiredService<IEwayBillService>().IsRequiredForDocumentAsync(world.InvoiceId)))
            .ShouldBeFalse();

        // Drop the threshold below the invoice and the same document now needs a bill — proving the
        // test reads the config row rather than a constant.
        await host.InScopeAsync(sp =>
            sp.GetRequiredService<IEinvoiceSettingsService>().SetEwayBillThresholdAsync(1_000m));

        (await host.InScopeAsync(sp =>
                sp.GetRequiredService<IEwayBillService>().IsRequiredForDocumentAsync(world.InvoiceId)))
            .ShouldBeTrue();
    }

    [Fact]
    public async Task UpdatePartBAsync_ChangesTheVehicleOnAnIssuedBill()
    {
        var portal = new RecordedIrpServer();
        await using var host = EinvoiceTestWorld.NewHost(portal);
        var world = await EinvoiceTestWorld.ArrangeAsync(host);

        await host.InScopeAsync(sp =>
            sp.GetRequiredService<IEinvoiceService>().GenerateAsync(world.InvoiceId));

        var bill = await host.InScopeAsync(sp =>
            sp.GetRequiredService<IEwayBillService>().GenerateAsync(world.InvoiceId, 450, ByRoad));

        var updated = await host.InScopeAsync(sp =>
            sp.GetRequiredService<IEwayBillService>().UpdatePartBAsync(
                bill.Id,
                ByRoad with { VehicleNumber = "KA02CD5678" }));

        updated.VehicleNumber.ShouldBe("KA02CD5678");
        portal.Calls.ShouldContain(nameof(RecordedIrpServer.UpdateEwayBillPartBAsync));
    }

    [Fact]
    public async Task GenerateAsync_ByRailWithoutATransportDocument_IsRefused()
    {
        var portal = new RecordedIrpServer();
        await using var host = EinvoiceTestWorld.NewHost(portal);
        var world = await EinvoiceTestWorld.ArrangeAsync(host);

        await host.InScopeAsync(sp =>
            sp.GetRequiredService<IEinvoiceService>().GenerateAsync(world.InvoiceId));

        await Should.ThrowAsync<ArgumentException>(() => host.InScopeAsync(sp =>
            sp.GetRequiredService<IEwayBillService>().GenerateAsync(
                world.InvoiceId,
                450,
                new EwayBillPartB(TransportMode.Rail, VehicleType.Regular))));
    }

    [Fact]
    public async Task CancelAsync_WithinTheWindow_CancelsAtThePortal()
    {
        var portal = new RecordedIrpServer();
        await using var host = EinvoiceTestWorld.NewHost(portal);
        var world = await EinvoiceTestWorld.ArrangeAsync(host);

        await host.InScopeAsync(sp =>
            sp.GetRequiredService<IEinvoiceService>().GenerateAsync(world.InvoiceId));

        var bill = await host.InScopeAsync(sp =>
            sp.GetRequiredService<IEwayBillService>().GenerateAsync(world.InvoiceId, 450, ByRoad));

        // Inside the 24 hours from the portal's 2026-09-17 17:45 IST issue time.
        host.Clock.UtcNow = new DateTimeOffset(2026, 9, 17, 18, 0, 0, TimeSpan.Zero);

        var cancelled = await host.InScopeAsync(sp =>
            sp.GetRequiredService<IEwayBillService>().CancelAsync(bill.Id, "2", "Consignment withdrawn"));

        cancelled.Status.ShouldBe(EwayBillStatus.Cancelled);
    }

    [Fact]
    public async Task CancelAsync_AfterTheWindow_IsRefusedWithoutCallingThePortal()
    {
        var portal = new RecordedIrpServer();
        await using var host = EinvoiceTestWorld.NewHost(portal);
        var world = await EinvoiceTestWorld.ArrangeAsync(host);

        await host.InScopeAsync(sp =>
            sp.GetRequiredService<IEinvoiceService>().GenerateAsync(world.InvoiceId));

        var bill = await host.InScopeAsync(sp =>
            sp.GetRequiredService<IEwayBillService>().GenerateAsync(world.InvoiceId, 450, ByRoad));

        host.Clock.UtcNow = new DateTimeOffset(2026, 9, 19, 0, 0, 0, TimeSpan.Zero);

        var callsBefore = portal.Calls.Count;

        await Should.ThrowAsync<InvalidOperationException>(() => host.InScopeAsync(sp =>
            sp.GetRequiredService<IEwayBillService>().CancelAsync(bill.Id, "2")));

        portal.Calls.Count.ShouldBe(callsBefore);
    }

    [Fact]
    public async Task ExtendValidityAsync_RecordsTheExpiryThePortalGrants()
    {
        var portal = new RecordedIrpServer();
        await using var host = EinvoiceTestWorld.NewHost(portal);
        var world = await EinvoiceTestWorld.ArrangeAsync(host);

        await host.InScopeAsync(sp =>
            sp.GetRequiredService<IEinvoiceService>().GenerateAsync(world.InvoiceId));

        var bill = await host.InScopeAsync(sp =>
            sp.GetRequiredService<IEwayBillService>().GenerateAsync(world.InvoiceId, 450, ByRoad));

        var extended = await host.InScopeAsync(sp =>
            sp.GetRequiredService<IEwayBillService>()
                .ExtendValidityAsync(bill.Id, remainingDistanceKilometres: 120, "1", "Vehicle broke down"));

        // The recorded portal grants 2026-09-25 17:45 IST = 12:15 UTC. An extension is granted, never
        // calculated by us.
        extended.ValidUntilUtc.ShouldBe(new DateTimeOffset(2026, 9, 25, 12, 15, 0, TimeSpan.Zero));
        extended.DistanceKilometres.ShouldBe(120);
    }

    [Fact]
    public async Task GenerateAsync_WhenThePortalRefuses_MarksTheBillRejectedAndKeepsTheReason()
    {
        var portal = new RecordedIrpServer();
        await using var host = EinvoiceTestWorld.NewHost(portal);
        var world = await EinvoiceTestWorld.ArrangeAsync(host);

        await host.InScopeAsync(sp =>
            sp.GetRequiredService<IEinvoiceService>().GenerateAsync(world.InvoiceId));

        portal.NextCallRejectionMessage = "4002: Invalid vehicle number format";

        var bill = await host.InScopeAsync(sp =>
            sp.GetRequiredService<IEwayBillService>().GenerateAsync(world.InvoiceId, 450, ByRoad));

        bill.Status.ShouldBe(EwayBillStatus.Rejected);
        bill.LastErrorText!.ShouldContain("4002");
    }
}
